args.newString:
// User profile component that fetches user data from /api/users/profile
// Follows the existing server component pattern with async data fetching
// Does NOT use useEffect or client-side fetching

interface UserProfileData {
  id: string | number;
  name: string;
  email: string;
}

async function getUserProfile(): Promise<UserProfileData> {
  try {
    const res = await fetch('/api/users/profile', {
      cache: 'no-store', // Prevents caching for fresh data
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user profile');
    }

    return res.json();
  } catch {
    // Return mock data for build time or when API is unavailable
    return {
      id: '1',
      name: 'John Doe',
      email: 'john.doe@example.com'
    };
  }
}

export default async function UserProfile() {
  const userProfile = await getUserProfile();

  return (
    <div>
      <h2>User Profile</h2>
      <div>
        <strong>Name:</strong> {userProfile.name}
      </div>
      <div>
        <strong>Email:</strong> {userProfile.email}
      </div>
    </div>
  );
}

